    }    else if (value is PermissionResourceMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.index);
    }    else if (value is PermissionDecisionMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.index);
    }    else if (value is JsDialogTypeMessage) {
      buffer.putUint8(138);
